// ==UserScript==
// @name         福利吧全能助手
// @namespace    https://greasyfork.org/zh-CN/users/1607776-lonhey
// @version      1.0.3
// @description  福利吧全能助手（移动端配置界面适配维护版）
// @author       lonhey
// @homepageURL  https://github.com/lingyuncrystal/fuliba-assistant-mobile
// @supportURL   https://github.com/lingyuncrystal/fuliba-assistant-mobile/issues
// @updateURL    https://raw.githubusercontent.com/lingyuncrystal/fuliba-assistant-mobile/main/fuliba-assistant.user.js
// @downloadURL  https://raw.githubusercontent.com/lingyuncrystal/fuliba-assistant-mobile/main/fuliba-assistant.user.js
// @match        *://*.wnflb00.com/*
// @match        *://*.wnflb99.com/*
// @match        *://*.wnflb2023.com/*
// @match        *://*.bbs.fuliba.net/*
// @match        *://*.fuliba.net/*
// @match        *://*.f.uliba.net/*
// @match        *://*.fuliba66.net/*
// @match        *://*.fuliba2023.net/*
// @match        *://*.fuliba2025.net/*
// @grant        GM_setValue
// @grant        GM_getValue
// @grant        GM_xmlhttpRequest
// @grant        GM_registerMenuCommand
// @grant        GM_addStyle
// @grant        GM_setClipboard
// @connect      pan.baidu.com
// @connect      pan.quark.cn
// @connect      drive-h.quark.cn
// @connect      whatslink.info
// @run-at       document-start
// @noframes
// ==/UserScript==

// 移动端设置面板适配：保留桌面布局，仅覆盖窄屏下的尺寸与交互。
GM_addStyle(`
@media (max-width: 768px) {
    .fuliba-panel,
    .fuliba-panel.fuliba-panel-settings {
        top: calc(env(safe-area-inset-top, 0px) + 8px) !important;
        right: calc(env(safe-area-inset-right, 0px) + 8px) !important;
        bottom: calc(env(safe-area-inset-bottom, 0px) + 8px) !important;
        left: calc(env(safe-area-inset-left, 0px) + 8px) !important;
        width: auto !important;
        max-width: none !important;
        height: auto !important;
        max-height: none !important;
        margin: 0 !important;
        transform: none !important;
        box-sizing: border-box !important;
        border-radius: 8px !important;
        overscroll-behavior: contain;
    }

    .fuliba-panel-header {
        min-height: 48px;
        padding: 8px 12px !important;
        box-sizing: border-box;
    }

    .fuliba-panel-title {
        font-size: 16px !important;
    }

    .fuliba-panel-close {
        width: 44px !important;
        height: 44px !important;
        flex: 0 0 44px;
        font-size: 24px !important;
        touch-action: manipulation;
    }

    .fuliba-tabs {
        gap: 8px !important;
        padding: 8px 12px 0 !important;
        overflow-x: auto;
        overflow-y: hidden;
        scrollbar-width: none;
        -webkit-overflow-scrolling: touch;
    }

    .fuliba-tabs::-webkit-scrollbar {
        display: none;
    }

    .fuliba-tab {
        min-height: 44px;
        padding: 8px 14px !important;
        flex: 0 0 auto;
        touch-action: manipulation;
    }

    .fuliba-panel-body {
        min-height: 0;
        padding: 12px !important;
        overflow-x: hidden !important;
        overflow-y: auto !important;
        -webkit-overflow-scrolling: touch;
        overscroll-behavior: contain;
    }

    .fuliba-sections {
        grid-template-columns: minmax(0, 1fr) !important;
        gap: 10px !important;
    }

    .fuliba-section {
        min-width: 0;
        padding: 12px !important;
    }

    .fuliba-setting-item {
        min-height: 44px !important;
        gap: 10px;
    }

    .fuliba-setting-label {
        min-width: 0;
        margin-right: 0 !important;
        font-size: 14px !important;
        line-height: 1.4;
    }

    .fuliba-input-sm,
    .fuliba-input-md,
    .fuliba-select,
    .fuliba-textarea,
    .fuliba-textarea-sm {
        max-width: 100% !important;
        box-sizing: border-box !important;
        font-size: 16px !important;
    }

    .fuliba-input-sm,
    .fuliba-input-md,
    .fuliba-select {
        min-height: 40px;
    }

    .fuliba-textarea,
    .fuliba-textarea-sm {
        resize: vertical;
    }

    .fuliba-panel-footer {
        padding: 8px 12px calc(8px + env(safe-area-inset-bottom, 0px)) !important;
        flex-wrap: wrap;
        gap: 8px !important;
    }

    .fuliba-footer-left,
    .fuliba-footer-right {
        display: flex;
        flex: 1 1 100%;
        gap: 8px !important;
    }

    .fuliba-footer-right {
        justify-content: flex-end;
    }

    .fuliba-btn {
        min-height: 44px;
        padding: 8px 14px !important;
        touch-action: manipulation;
    }
}

@media (max-width: 420px) {
    .fuliba-setting-item {
        align-items: flex-start !important;
        flex-wrap: wrap;
    }

    .fuliba-setting-label {
        flex: 1 1 calc(100% - 64px) !important;
    }

    .fuliba-setting-item > .fuliba-input-sm,
    .fuliba-setting-item > .fuliba-input-md,
    .fuliba-setting-item > .fuliba-select,
    .fuliba-setting-item > .fuliba-textarea-sm {
        flex: 1 1 100%;
        width: 100% !important;
    }

    .fuliba-footer-left .fuliba-btn,
    .fuliba-footer-right .fuliba-btn {
        flex: 1 1 0;
    }
}
`);

// 头像模糊兼容层：原脚本会在 fuliba*.net 上强制停用该设置，且未覆盖手机端常见头像结构。
// 该设置应独立于“图片模糊”，保存配置并刷新页面后生效。
const avatarBlurStorageKey = `flb_${location.hostname}_blurAvatar`;
if (GM_getValue(avatarBlurStorageKey, false)) {
    GM_addStyle(`
        td.pls img,
        .avatar img,
        .favatar img,
        img.avatar,
        .thread-item-author img,
        .k-viewavatar img,
        .user-avatar img,
        .author-avatar img,
        .comment-author img.avatar,
        .comt-avatar img {
            filter: blur(14px) brightness(0.8) !important;
            transition: filter 0.3s ease;
        }

        td.pls img:hover,
        .avatar img:hover,
        .favatar img:hover,
        img.avatar:hover,
        .thread-item-author img:hover,
        .k-viewavatar img:hover,
        .user-avatar img:hover,
        .author-avatar img:hover,
        .comment-author img.avatar:hover,
        .comt-avatar img:hover {
            filter: blur(0) brightness(1) !important;
        }

        td.pls .md_ctrl img,
        td.pls img[src*="medal"],
        td.pls img[id^="md_"],
        .badge img,
        .medal img {
            filter: none !important;
        }
    `);
}

